// Browser prototype administration. This is not server authentication or database backup.
const ADMINKEY='power-mes-admin-state-v1',AUTHKEY='power-mes-auth-v1',AUDITKEY='power-mes-admin-audit-v1',BACKUPKEY='power-mes-backups-v1';
const demoAccounts={admin:{name:'系统管理员',id:'ADMIN-001',role:'admin',label:'系统管理员'},supervisor:{name:'王主管',id:'EMP-001',role:'supervisor',label:'生产主管'},quality:{name:'刘敏',id:'EMP-012',role:'quality',label:'质量主管'},operator:{name:'张伟',id:'EMP-008',role:'operator',label:'工位操作员'}};
let auth=null,adminAudit=[],backupHistory=[],pendingRestore=null,restoreName='';let adminSettings={factory:'智造电子 · 充电宝工厂',timezone:'Asia/Shanghai',shift:'08:00–20:00',snRule:'PB + 日期 + 六位流水号',heartbeat:'60',retention:'180'};
try{let state=JSON.parse(localStorage.getItem(ADMINKEY)||'null');if(state){if(Array.isArray(state.orders))orders=state.orders;if(Array.isArray(state.messages))msgs=state.messages;if(state.settings)adminSettings={...adminSettings,...state.settings}}let a=JSON.parse(sessionStorage.getItem(AUTHKEY)||'null');if(a&&demoAccounts[a.account]&&a.expires>Date.now()){auth={...demoAccounts[a.account],account:a.account,expires:a.expires}}adminAudit=JSON.parse(localStorage.getItem(AUDITKEY)||'[]');backupHistory=JSON.parse(localStorage.getItem(BACKUPKEY)||'[]')}catch{}if(!Array.isArray(adminAudit))adminAudit=[];if(!Array.isArray(backupHistory))backupHistory=[];
function persistAdmin(){localStorage.setItem(ADMINKEY,JSON.stringify({orders,messages:msgs,settings:adminSettings}))}
function adminLog(action,object,result='成功'){adminAudit.unshift({time:new Date().toLocaleString('zh-CN',{hour12:false}),user:auth?.name||'未登录',action,object,result});adminAudit=adminAudit.slice(0,500);localStorage.setItem(AUDITKEY,JSON.stringify(adminAudit))}
function requireAdmin(){if(auth?.role!=='admin'){toast('当前角色无系统管理权限');return false}return true}
function allowedPage(p){if(!auth)return false;if(auth.role==='admin')return true;if(['backup','settings','users'].includes(p))return false;if(auth.role==='quality')return ['overview','quality','rework','sop','trace','reports','messages','audit','login'].includes(p);if(auth.role==='operator')return false;return p!=='login'}
function loginScreen(){return `<div class="mes-login"><section class="login-intro"><div class="login-logo"><span>ϟ</span> POWER MES</div><div><div class="eyebrow">MANUFACTURING EXECUTION SYSTEM</div><h1>每一道工序，<br>都有据可循。</h1><p>从主码、电芯、测试到 SN 与包装，<br>让生产执行、质量与追溯紧密连接。</p><div class="login-points"><span>01　强制工序流转</span><span>02　受控 SOP 作业</span><span>03　仪器结果自动接入</span></div></div><small>智造 MES · 充电宝生产执行系统</small></section><section class="login-side"><div class="login-card"><div class="eyebrow">WELCOME BACK</div><h1>登录生产工作台</h1><p class="sub">使用已分配的账号进入对应工作空间</p><label class="field">账号<input id="adminAccount" autocomplete="username" placeholder="admin / supervisor / quality / operator" value="admin"></label><label class="field">密码<input id="adminPassword" type="password" autocomplete="current-password" placeholder="输入演示密码" onkeydown="if(event.key==='Enter')adminLogin()"></label><button class="primary bigbtn" style="margin-top:18px" onclick="adminLogin()">登录</button><div class="login-demo"><b>演示账号</b><div class="actions">${Object.entries(demoAccounts).map(([key,a])=>button(a.label,`$('#adminAccount').value='${key}';$('#adminPassword').focus()`)).join('')}</div><p>统一演示密码：<code>demo123</code></p></div><p class="hint">当前为浏览器原型，账号与权限仅用于交互演示，不能代替服务端认证。</p></div></section></div>`}
function adminLogin(){let account=$('#adminAccount').value.trim(),password=$('#adminPassword').value;if(!demoAccounts[account]||password!=='demo123'){toast('账号或演示密码不正确');return}auth={...demoAccounts[account],account,expires:Date.now()+8*60*60*1000};sessionStorage.setItem(AUTHKEY,JSON.stringify({account,expires:auth.expires}));wfUser={name:auth.name,id:auth.id};sessionStorage.setItem('mes-demo-user',JSON.stringify(wfUser));adminLog('登录','管理后台 / '+auth.label);page='overview';mode=auth.role==='operator'?'station':'pc';closeModal();render()}
function adminLogout(){adminLog('退出登录','当前设备');auth=null;sessionStorage.removeItem(AUTHKEY);sessionStorage.removeItem('mes-demo-user');wfCode='';autoPending=false;closeModal();mode='pc';page='login';render()}
function adminAccountMenu(){modal('账号与会话',detailRows([['姓名',escapeHtml(auth.name)],['账号',escapeHtml(auth.account)],['角色',auth.label],['工号',escapeHtml(auth.id)],['会话有效期','本次演示登录后 8 小时']])+`<p class="hint">正式账号、密码哈希和权限校验需由服务端处理。</p>`,button('退出登录',"adminLogout()",'danger')+button('关闭','closeModal()'))}
navs[navs.length-1][1]=[['users','♙','用户与角色'],['audit','≡','操作日志'],['backup','⤓','备份与恢复'],['settings','⚙','系统设置']];names.backup='备份与恢复';names.users='用户与角色';names.audit='操作日志';
renderers.users=function(){return heading('用户与角色','按岗位分配生产、质量和系统管理职责')+`<div class="notice">账号权限为原型演示。正式系统需要服务端用户目录、密码策略和接口权限校验。</div>`+panel('账号目录',table(['账号','姓名 / 工号','角色','主要职责','状态'],Object.entries(demoAccounts).map(([key,a])=>[key,`${a.name}<small>${a.id}</small>`,a.label,{admin:'全部模块、系统配置、备份恢复',supervisor:'工单、排产、设备、生产协同',quality:'检验、返修、SOP、追溯与报表',operator:'当前工位扫码、SOP 与消息'}[a.role],badge('启用')])))+panel('角色权限矩阵',table(['能力','系统管理员','生产主管','质量主管','操作员'],[['生产工单 / 排产','✓','✓','只读','—'],['质量检验 / 返修','✓','查看','✓','工位执行'],['SOP / 追溯','✓','✓','✓','本工位'],['用户 / 系统设置','✓','—','—','—'],['备份 / 恢复','✓','—','—','—']]))};
renderers.audit=function(){return heading('操作日志','查看登录、系统配置、备份与恢复的演示审计记录')+panel('操作记录',table(['时间','操作人','操作','对象','结果'],adminAudit.length?adminAudit.map(a=>[escapeHtml(a.time),escapeHtml(a.user),escapeHtml(a.action),escapeHtml(a.object),badge(a.result)]):[['—','—','暂无记录','—','—']]));};
renderers.settings=function(){return heading('系统设置','工厂、班次、条码与设备规则')+panel('工厂基础配置',`<div class="formgrid">${[['factory','工厂名称'],['timezone','时区'],['shift','日班时间'],['snRule','SN 规则说明'],['heartbeat','设备心跳超时（秒）'],['retention','消息保留天数']].map(([k,label])=>`<label class="field">${label}<input id="cfg-${k}" value="${escapeHtml(adminSettings[k])}"></label>`).join('')}</div><div style="margin-top:20px">${button('保存配置',"saveAdminSettings()",'primary')}</div>`)+panel('数据与运维',`<div class="lineitem"><div class="fill"><b>数据备份与恢复</b><p class="sub">导出当前演示数据，校验备份文件并预览恢复范围。</p></div>${button('打开备份管理',"go('backup')")}</div><div class="lineitem"><div class="fill"><b>服务器、账号与数据库</b><p class="sub">正式版需接入局域网 MES 服务、服务端认证与数据库备份。</p></div>${badge('待服务端接入')}</div>`)};
function saveAdminSettings(){if(!requireAdmin())return;let next={};for(let k of Object.keys(adminSettings)){let v=$('#cfg-'+k).value.trim();if(!v){toast('请完整填写配置');return}next[k]=v}if(!/^\d+$/.test(next.heartbeat)||Number(next.heartbeat)<1||!/^\d+$/.test(next.retention)||Number(next.retention)<1){toast('超时与保留天数必须为正整数');return}adminSettings=next;persistAdmin();adminLog('修改系统配置',adminSettings.factory);toast('配置已保存至当前浏览器')}
function backupCounts(data){return detailRows([['生产工单',data.orders.length+' 条'],['产品与条码绑定',data.units.length+' 台'],['仪器测试记录',data.units.reduce((a,u)=>a+u.tests.length,0)+' 条'],['扫码 / 上传日志',data.scanLogs.length+' 条'],['车间消息',data.messages.length+' 条'],['系统配置','1 组']])}
function backupData(){return JSON.parse(JSON.stringify({orders,units,scanLogs,messages:msgs,settings:adminSettings}))}
function backupHistorySave(){localStorage.setItem(BACKUPKEY,JSON.stringify(backupHistory.slice(0,100)))}
renderers.backup=function(){return heading('备份与恢复','保存可导出的数据快照，校验后恢复当前演示环境',button('创建并下载备份',"downloadBackup()",'primary'))+`<div class="notice">当前范围：本浏览器原型数据。不是服务器数据库备份；不包含登录密码、服务器地址、SOP 附件或真实设备原始文件。</div>`+stats([['产品记录',String(units.length),'主码、电芯、SN 与包装关联'],['测试记录',String(units.reduce((a,u)=>a+u.tests.length,0)),'保留 PASS / FAIL 及复测'],['生产工单',String(orders.length),'工单列表及进度'],['最近备份',backupHistory.length?backupHistory[0].date.slice(5,10):'尚未备份','仅记录本浏览器的备份操作']])+`<div class="gridhalf">${panel('导出数据快照',backupCounts(backupData())+`<p class="hint">JSON 格式 · SHA-256 内容校验 · 不包含账号凭证</p>${button('创建并下载备份',"downloadBackup()",'primary')}`)}${panel('从备份文件恢复',`<p class="sub">选择本系统导出的备份文件。系统先检查版本、结构与内容校验值，再展示恢复预览。</p><label class="field" style="margin:20px 0">备份文件（JSON，最大 10 MB）<input id="restoreFile" type="file" accept=".json,application/json" onchange="inspectRestore(this)"></label><div id="restorePreview"><p class="hint">尚未选择文件。选择后不会立即覆盖数据。</p></div>`)}</div>`+panel('备份操作记录',table(['时间','文件名','产品 / 测试','大小','操作人','结果'],backupHistory.length?backupHistory.map(b=>[escapeHtml(b.date),escapeHtml(b.name),b.units+' / '+b.tests,(b.bytes/1024).toFixed(1)+' KB',escapeHtml(b.user),badge(b.action)]):[['—','暂无备份记录','—','—','—','—']]))};
async function hashBackup(data){let bytes=new TextEncoder().encode(JSON.stringify(data));let digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function triggerDownload(name,content){let url=URL.createObjectURL(new Blob([content],{type:'application/json;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function downloadBackup(){if(!requireAdmin())return;try{persistAdmin();let data=backupData(),stamp=new Date().toISOString(),name='MES-backup-'+stamp.replace(/[:.]/g,'-')+'.json';let b={format:'POWER-MES-BROWSER-BACKUP',version:1,createdAt:stamp,scope:'browser-demo',sha256:await hashBackup(data),data};let content=JSON.stringify(b,null,2);triggerDownload(name,content);backupHistory.unshift({date:new Date().toLocaleString('zh-CN',{hour12:false}),name,units:data.units.length,tests:data.units.reduce((a,u)=>a+u.tests.length,0),bytes:new Blob([content]).size,user:auth.name,action:'已触发下载'});backupHistorySave();adminLog('创建备份',name);render();toast('备份下载已触发，请确认浏览器已保存文件')}catch(e){toast('备份未完成：'+e.message)}}
function validateBackupShape(b){if(!b||b.format!=='POWER-MES-BROWSER-BACKUP'||b.version!==1||b.scope!=='browser-demo'||!/^\w{64}$/.test(b.sha256||''))throw Error('不是受支持的 MES 备份文件');let d=b.data;if(!d||!Array.isArray(d.orders)||!Array.isArray(d.units)||!Array.isArray(d.scanLogs)||!Array.isArray(d.messages)||!d.settings)throw Error('备份数据结构不完整');function walk(v,depth=0){if(depth>20)throw Error('文件结构嵌套过深');if(v&&typeof v==='object')for(let k of Object.keys(v)){if(['__proto__','constructor','prototype'].includes(k))throw Error('文件包含无效字段');walk(v[k],depth+1)}}walk(d);if(d.units.length>100000||d.orders.length>10000||d.scanLogs.length>100000||d.messages.length>10000)throw Error('记录数超出原型支持范围');let main=new Set(),sn=new Set(),cells=new Set();for(let u of d.units){if(!u||typeof u.main!=='string'||!u.main||main.has(u.main)||!Array.isArray(u.tests)||!Array.isArray(u.history))throw Error('产品主码重复或记录格式异常');main.add(u.main);for(let k of ['cell','sn','pack'])if(typeof u[k]!=='string')throw Error('绑定码格式错误');if(u.sn&&sn.has(u.sn))throw Error('备份含重复 SN');if(u.cell&&cells.has(u.cell))throw Error('备份含重复电芯码');if(u.sn)sn.add(u.sn);if(u.cell)cells.add(u.cell);if(u.sn&&(!u.cell||!u.tests.length||u.tests.at(-1).result!=='PASS'))throw Error('SN 绑定缺少合格前序');if(u.pack&&!u.sn)throw Error('包装绑定缺少 SN');for(let t of u.tests)if(!['PASS','FAIL'].includes(t.result)||typeof t.record!=='string'||typeof t.time!=='string'||!Number.isFinite(t.voltage)||!Number.isFinite(t.current))throw Error('测试数据格式错误');for(let h of u.history)if(!['title','note','time'].every(k=>typeof h[k]==='string'))throw Error('履历格式错误')}for(let r of d.orders)if(!Array.isArray(r)||r.length!==9||!r.every(v=>['string','number'].includes(typeof v)&&!(typeof v==='string'&&/[<>]/.test(v)))||!Number.isFinite(Number(r[6])))throw Error('工单格式错误');for(let m of d.messages)if(!['title','text','type','time'].every(k=>typeof m[k]==='string')||typeof m.read!=='boolean')throw Error('消息格式错误');for(let x of d.scanLogs)if(!['time','order','station','user','type','code','main','result','note'].every(k=>typeof x[k]==='string')||!Number.isInteger(x.stage)||x.stage<0||x.stage>4)throw Error('扫码日志格式错误');for(let k of Object.keys(adminSettings))if(typeof d.settings[k]!=='string')throw Error('系统配置格式错误');return d}
async function inspectRestore(input){if(!requireAdmin())return;pendingRestore=null;let file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024){$('#restorePreview').textContent='文件超过 10 MB，请选择较小的备份。';return}try{let b=JSON.parse(await file.text());validateBackupShape(b);if(await hashBackup(b.data)!==b.sha256)throw Error('校验值不匹配，文件可能已被修改');pendingRestore=b;restoreName=file.name;$('#restorePreview').innerHTML=`<div class="notice">文件校验通过 · ${escapeHtml(file.name)}</div>${backupCounts(b.data)}<p class="hint">恢复将替换当前浏览器的上述数据。设备服务器地址与登录会话保留。</p>${button('查看恢复确认',"confirmRestore()",'danger')}`;adminLog('校验恢复文件',file.name)}catch(e){$('#restorePreview').textContent='校验失败：'+e.message;adminLog('校验恢复文件',file.name,'失败')}}
function confirmRestore(){if(!requireAdmin()||!pendingRestore)return;modal('确认恢复数据',`<div class="statusbox fail"><h2>将覆盖当前浏览器演示数据</h2><p>备份文件：${escapeHtml(restoreName)}</p></div>${backupCounts(pendingRestore.data)}<label class="checkrow"><input id="restoreConfirm" type="checkbox">我已确认恢复范围，并已下载当前数据备份</label>`,button('取消','closeModal()')+button('执行恢复',"applyRestore()",'danger'))}
function applyRestore(){if(!requireAdmin()||!pendingRestore)return;if(!$('#restoreConfirm').checked){toast('请确认恢复范围并备份当前数据');return}let d=pendingRestore.data;try{validateBackupShape(pendingRestore);let keys=[ADMINKEY,WFKEY,SCANKEY],old=keys.map(k=>localStorage.getItem(k));try{localStorage.setItem(ADMINKEY,JSON.stringify({orders:d.orders,messages:d.messages,settings:d.settings}));localStorage.setItem(WFKEY,JSON.stringify(d.units));localStorage.setItem(SCANKEY,JSON.stringify(d.scanLogs))}catch(e){keys.forEach((k,i)=>{if(old[i]===null)localStorage.removeItem(k);else localStorage.setItem(k,old[i])});throw e}orders=d.orders;msgs=d.messages;units=d.units;scanLogs=d.scanLogs;adminSettings=d.settings;wfCode='';autoPending=false;wfChecked=false;adminLog('恢复备份',restoreName);pendingRestore=null;closeModal();render();toast('恢复完成，当前扫码上下文已清空')}catch(e){toast('恢复失败：'+e.message)}}
const goBeforeAdmin=go;go=function(p){if(p==='login'){adminAccountMenu();return}if(!allowedPage(p)){toast('当前角色无权访问此模块');return}goBeforeAdmin(p)};
const modeBeforeAdmin=setMode;setMode=function(m){if(!auth){mode='pc';page='login';render();return}if(auth.role==='operator'&&m!=='station'){toast('操作员仅能进入工位端');return}modeBeforeAdmin(m)};
const adminRenderBase=render;render=function(){if(auth&&auth.expires<=Date.now()){auth=null;sessionStorage.removeItem(AUTHKEY)}if(!auth){$('#app').innerHTML=loginScreen();return}if(mode==='pc'&&!allowedPage(page))page='overview';persistAdmin();adminRenderBase();if(mode==='pc'){document.querySelectorAll('.nav button').forEach(b=>{let m=b.getAttribute('onclick')?.match(/go\('([^']+)'\)/);if(m&&!allowedPage(m[1]))b.style.display='none'});let right=$('.topright');if(right)right.innerHTML=`<span class="optional">${badge(auth.label)}</span>${button('✉ '+msgs.filter(m=>!m.read).length,"go('messages')")}<button onclick="adminAccountMenu()">${escapeHtml(auth.name)} ▾</button>`}};
const userMenuBeforeAdmin=wfUserMenu;wfUserMenu=function(){modal('当前登录用户',detailRows([['姓名',escapeHtml(auth.name)],['工号',auth.id],['角色',auth.label],['当前工位',stationId()+' · '+steps[wfStage]],['MES 服务器',escapeHtml(mesServer)]]),button('服务器设置',"configureServer()")+(auth.role!=='operator'?button('返回管理后台',"closeModal();setMode('pc')"):'')+button('退出登录',"adminLogout()",'danger'))};
render();
